def compose(source:str)->str:
    if hashlib.sha256(source.encode("utf-8")).hexdigest()!=BASE_SHA256:
        raise ValueError("exact frozen four-role carrier is required")
    result=source
    for old,new in EDITS:
        if result.count(old)!=1:raise ValueError("mechanical edit boundary must be unique")
        result=result.replace(old,new,1)
    recovered=result
    for old,new in reversed(EDITS):
        if recovered.count(new)!=1:raise ValueError("mechanical reverse boundary must be unique")
        recovered=recovered.replace(new,old,1)
    if recovered!=source:raise ValueError("old carrier changed outside declared boundaries")
    if hashlib.sha256(result.encode("utf-8")).hexdigest()!=RESULT_SHA256:
        raise ValueError("six-role source result mismatch")
    return result

def main():
    import argparse
    p=argparse.ArgumentParser()
    p.add_argument("base",type=Path)
    p.add_argument("output",type=Path)
    a=p.parse_args()
    raw=a.base.read_bytes()
    source=raw.decode("utf-8")
    result=compose(source)
    if a.base.read_bytes()!=raw:raise ValueError("base source changed during composition")
    a.output.write_bytes(result.encode("utf-8"))
    print(a.output.name,len(result.encode("utf-8")),RESULT_SHA256)
if __name__=="__main__":main()
